using KitWright.Editor.Tools.Scripting;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
using TMPro;
using System.Text;

public class CommandScript : IKitWrightCommand
{
    public void Execute(ExecutionContext ctx)
    {
        var sb = new StringBuilder();
        var scene = EditorSceneManager.GetActiveScene();
        if (!scene.path.Contains("LoginMenu"))
            scene = EditorSceneManager.OpenScene("Assets/Project/LoginMenu.unity");

        Transform FindDeep(string name)
        {
            foreach (var t in Resources.FindObjectsOfTypeAll<Transform>())
            {
                if (EditorUtility.IsPersistent(t.gameObject)) continue;
                if (t.name == name) return t;
            }
            return null;
        }

        var logo = FindDeep("Logo_Railbound_Yellow");
        var panel = FindDeep("LoginPanel");
        if (logo != null && panel != null)
        {
            ctx.RegisterObjectModification(logo.gameObject);
            logo.SetParent(panel, false);
            logo.SetAsFirstSibling();
            var rt = logo.GetComponent<RectTransform>();
            rt.anchorMin = new Vector2(0.5f, 1f);
            rt.anchorMax = new Vector2(0.5f, 1f);
            rt.pivot = new Vector2(0.5f, 0f);
            rt.sizeDelta = new Vector2(280f, 72f);
            rt.anchoredPosition = new Vector2(0f, 16f);
            logo.gameObject.SetActive(true);
            sb.AppendLine("logo -> LoginPanel");
        }

        // Brand title text on LoginPanel if a title TMP exists
        TMP_Text brand = null;
        if (panel != null)
        {
            foreach (var t in panel.GetComponentsInChildren<TMP_Text>(true))
            {
                if (t.name == "GameTitle" || t.name == "Title" || t.name == "BrandTitle")
                { brand = t; break; }
            }
            if (brand == null)
            {
                var go = new GameObject("BrandTitle", typeof(RectTransform), typeof(CanvasRenderer), typeof(TextMeshProUGUI));
                ctx.RegisterObjectCreation(go);
                go.transform.SetParent(panel, false);
                var rt = go.GetComponent<RectTransform>();
                rt.anchorMin = new Vector2(0.5f, 1f);
                rt.anchorMax = new Vector2(0.5f, 1f);
                rt.pivot = new Vector2(0.5f, 1f);
                rt.sizeDelta = new Vector2(520f, 48f);
                rt.anchoredPosition = new Vector2(0f, -86f);
                brand = go.GetComponent<TextMeshProUGUI>();
                brand.alignment = TextAlignmentOptions.Center;
                brand.fontSize = 36;
                brand.fontStyle = FontStyles.Bold;
                sb.AppendLine("created BrandTitle");
            }
            ctx.RegisterObjectModification(brand);
            brand.text = "RAILBOUND";
            brand.color = new Color(1f, 0.816f, 0f, 1f);

            var loginUi = Object.FindObjectOfType<LoginUI>(true);
            if (loginUi != null)
            {
                var so = new SerializedObject(loginUi);
                var gt = so.FindProperty("gameTitle");
                if (gt != null && gt.objectReferenceValue == null)
                {
                    gt.objectReferenceValue = brand;
                    so.ApplyModifiedPropertiesWithoutUndo();
                    sb.AppendLine("wired gameTitle");
                }
                ctx.RegisterObjectModification(loginUi);
            }
        }

        // Ensure AccountLoginPopup starts visually hidden via canvas group if currently alpha 1
        var acct = FindDeep("AccountLoginPopup");
        if (acct != null)
        {
            var cg = acct.GetComponent<CanvasGroup>();
            if (cg != null)
            {
                ctx.RegisterObjectModification(cg);
                cg.alpha = 0f;
                cg.interactable = false;
                cg.blocksRaycasts = false;
                sb.AppendLine("hid AccountLoginPopup cg");
            }
        }

        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        ctx.ReturnValue = sb.ToString();
    }
}
